#!/usr/bin/env python3
"""Transform four exact native source faces with frozen approximate calibration.
Run extract.py, match-cad.py and fit.py separately to inspect/review calibration.
No new edge, buffer, point-derived footprint, clipping or repair is performed.
"""
import argparse,hashlib,json,subprocess
from pathlib import Path
import numpy as np
from shapely.geometry import shape,Point,mapping
from shapely.ops import transform
from pyproj import Transformer,Geod
P=Path(__file__).resolve().parent;ROOT=P.parents[3]
URL='https://njt.jog.gov.hu/document/4f/4fb0LL_EJR_84883813-Sopron_-_HESZmod_1_melleklet__SZT-Atnezeti_tervlapok.pdf'
read=lambda n:json.loads((P/n).read_text());sha=lambda n:hashlib.sha256((P/n).read_bytes()).hexdigest()
def encoded(o):return json.dumps(o,ensure_ascii=False,indent=2,allow_nan=False)+'\n'

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');args=ap.parse_args();native=read('native-source-polygons.json');reg=read('registration.json');src=read('source-extraction-proof.json');matrix=np.array(reg['page2PdfPointsToEovMatrix']);inverse=Transformer.from_crs(23700,4326,always_xy=True);metric=Transformer.from_crs(4326,23700,always_xy=True).transform;parent=shape(read('calibration-municipality.geojson')['geometry']);features=[];records=[];worlds=[]
 assert reg['registrationGeographicNamePointCount']==0 and reg['crossPageCadControlPairs']>=12
 for r in reg['inputs']:assert sha(r['path'])==r['sha256']
 def geographic(x,y,z=None):return inverse.transform(x*matrix[0,0]+y*matrix[1,0]+matrix[2,0],x*matrix[0,1]+y*matrix[1,1]+matrix[2,1])
 for r in native['records']:
  n=r['sourceUnitNumber'];p=shape(r['nativeGeometry']);world=transform(geographic,p);assert p.is_valid and world.is_valid;worlds.append(world);outside=transform(metric,world.difference(parent)).area;area=transform(metric,world).area;source_label=Point(r['sourceLabel']['pointInsideActualSourceFacePdfPoints']);assert p.covers(source_label);assert world.covers(transform(geographic,source_label))
  props={'name':r['name'],'shortSourceLabel':r['shortSourceLabel'],'municipality':'Sopron','boundaryKind':'planning_unit','canonicalNameIsNeighborhood':False,'sourceUnitNumber':n,'constituentFootprintsInvented':False,'sourcePeriod':'Plan TT08518-M1/24, page 1 visibly printed issue date 2024. 11. (November 2024); Annex 1/B to 39/2021. (XII.28.) municipal ordinance. Current legal validity not independently certified.','method':'Exact centreline of original native blue vector source strokes. Only the original 1238 line segments are noded and polygonized into 4 source-defined closed faces; no invented closing chord. Actual blue map-label positions identify each source face. Frozen approximate page 1 actual-municipal-perimeter-to-OSM registration in EOV, linked to page 2 by 4888 actual source CAD segment pairs. Inverse projection to WGS84. No name-point coordinates, clipping, snapping, buffers or geometry repair.','evidenceUrls':[URL],'sourceDocuments':[{'url':URL,'sha256':src['originalPdfSha256'],'archivedPdfSha256':src['archivedSourcePdfSha256'],'pdfPageOneBased':2,'annex':'1/B,39/2021.(XII.28.)','workNumber':'TT08518-M1/24'}],'sourceDocumentIsOfficialMunicipalPublication':True,'sourceIsOfficial':False,'sourceIsHardBoundary':False,'estimated':False,'georeferencingIsApproximate':True,'claimedAbsoluteAccuracyMetres':None,'usableForAddressAssignment':False,'reviewStatus':'historical_source_vector_review_required','currentNameStatus':'source_plan_label_not_independently_current_verified','sourceLabelEvidence':r['sourceLabel'],'municipalityOverlapFraction':1-outside/area,'outsideCurrentMunicipalityAreaM2':outside,'areaM2':abs(Geod(ellps='WGS84').geometry_area_perimeter(world)[0]),'reviewNotes':['These are 4 whole irregular geographic planning units, not 4 plan-sheet rectangles. The blue legend explicitly says city-region boundary; the plan also depicts regulation territorial scope.','Keep the complete source label. Bánfalva/Kutyahegy is a grouped unit and southeast is an economic planning area. No group footprint is copied onto constituent names.','Page1 municipal source line samples and thousands of cross-page real CAD endpoint pairs establish calculation provenance, not independent absolute geographic accuracy.','Whole-perimeter matching residuals and cross-page residuals are diagnostics. No independently surveyed or identified interior world controls are claimed.','An extracted-only .../2024 CAD placeholder is not visibly printed in the original rendered white block; it does not establish visible draft or approval status. Current legal validity remains unverified.','Unknown source reuse rights, current legal validity and absolute accuracy; address assignment remains disabled.'],'license':'Municipal plan reuse rights not independently established; ODbL applies to OSM calibration reference.'}
  features.append({'type':'Feature','id':f'manual:sopron-source-vector:{n}','geometry':mapping(world),'properties':props});records.append({'sourceUnitNumber':n,'name':r['name'],'nativeGeometrySha256':hashlib.sha256(encoded(r['nativeGeometry']).encode()).hexdigest(),'sourceNativeAreaPdfPointsSquared':p.area,'nativeSourceLabelInside':True,'geographicGeometryValid':world.is_valid,'geographicVertexCount':sum(len(x.coords) for x in [world.exterior,*world.interiors]),'sourcePolygonRingsUnchangedBeforeAffineAndProjection':True,'sourceGeographicLabelInside':True,'outsideCurrentMunicipalityAreaM2':outside,'municipalityOverlapFraction':1-outside/area,'clippedToCurrentMunicipality':False})
 overlaps=[worlds[i].intersection(worlds[j]).area for i in range(len(worlds)) for j in range(i)];assert max(overlaps)<=1e-16
 fc={'type':'FeatureCollection','features':features};proof={'schemaVersion':1,'inputs':[{'path':n,'sha256':sha(n)} for n in ['source-pages1-2.pdf','native-source-segments.json','native-source-polygons.json','source-extraction-proof.json','registration.json','calibration-municipality.geojson','cross-page-cad-controls.json','cross-page-cad-controls.json.gz']],'sourceUnits':4,'fineNeighbourhoodCount':0,'wholePlanningUnitCount':4,'geographicCoordinatesAreNativePdfCoordinates':False,'nativeSourceCoordinateSystem':'Page2 PDF points, origin top-left, y down','geographicOutputCrs':'EPSG4326','intermediateCrs':'EPSG23700','nativeBoundaryInterpretation':'Exact original vector-stroke centreline, not a raster inside-stroke contour.','sourceEdgesInvented':0,'geometryRepair':False,'clipping':False,'pointDerivedFootprints':False,'maximumPairwiseOverlapDegreesSquared':max(overlaps),'regressionMatrixPage2ToEov':matrix.tolist(),'absoluteBoundaryAccuracyMetres':None,'usableForAddressAssignment':False,'records':records}
 outputs={'source-vector.geojson':encoded(fc),'conversion-proof.json':encoded(proof)}
 for n,t in outputs.items():
  if args.check:assert (P/n).read_text()==t,n
  else:(P/n).write_text(t)
 print(encoded({'features':4,'fine':0,'planning':4,'names':[x['properties']['name'] for x in features],'pairwiseOverlapDegreesSquared':max(overlaps),'check':args.check}))
if __name__=='__main__':main()
